/// <summary>
///    AVA <c>AVACheckTitleIdTxt</c> method.  
/// </summary>
public void AVACheckAVAAffixTxt()
{
    if(this.Affix != '')
    {
        this.AVAAffixTxt = this.Affix;
    }
}

/// <summary>
///    AVA <c>update</c> method.
/// </summary>
public void update()
{
    this.AVACheckAVAAffixTxt();

    next update();
}

/// <summary>
///    AVA <c>insert</c> method.
/// </summary>
public void insert()
{
    this.AVACheckAVAAffixTxt();

    next insert();
}

/// <summary>
///    AVA <c>getTitleIdTranslation</c> method.
/// </summary>
/// <param name="_languageId">
///    <c>LanguageId</c> as type
/// </param>
/// <returns>
///    <c>smmContactPrivateTitle</c> as return value
/// </returns>
public smmContactPrivateTitle getAffixTranslation(LanguageId _languageId = CompanyInfo::languageId())
{
    smmContactPrivateTitle      retVal;
    AVADirNameAffixTranslation  locAVADirNameAffixTranslation;

    retVal = this.Affix;

    locAVADirNameAffixTranslation = AVADirNameAffixTranslation::findByDirNameAffixAndLanguage(this.RecId, _languageId);
    if(     locAVADirNameAffixTranslation.RecId
        &&  locAVADirNameAffixTranslation.AVAAffixTxt)
    {
        retVal = locAVADirNameAffixTranslation.AVAAffixTxt;
    }

    return retVal;
}

/// <summary>
///    AVA <c>findRecId</c> method.
/// </summary>
/// <param name="_recId">
///    <c>RecId</c> as type
/// </param>
/// <param name = "_forUpdate">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>DirNameAffix</c> as return value
/// </returns>
static DirNameAffix findRecId(  RecId   _recId,
                                boolean _forUpdate = false)
{
    DirNameAffix  dirNameAffix;

    if (_recId)
    {
        if (_forUpdate)
        {
            dirNameAffix.selectForUpdate (_forUpdate);
        }
        dirNameAffix.selectLocked    (_forUpdate);

        select firstonly dirNameAffix
        where dirNameAffix.RecId == _recId;

    }
    return dirNameAffix;
}
